-- Lead Tracker: people who asked about a job but aren't customers yet. Private to the owner. Money in cents.
create table if not exists public.leads (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users (id) on delete cascade, name text not null check (char_length(name) between 1 and 120), phone text not null default '' check (char_length(phone) <= 40), email text not null default '' check (char_length(email) <= 200), address text not null default '' check (char_length(address) <= 200), job text not null default '' check (char_length(job) <= 300), source text not null default '' check (char_length(source) <= 60), value_cents integer not null default 0 check (value_cents between 0 and 100000000), stage text not null default 'new' check (stage in ('new', 'contacted', 'quoted', 'scheduled', 'won', 'lost')), follow_up_on date, follow_up_note text not null default '' check (char_length(follow_up_note) <= 200), notes text not null default '' check (char_length(notes) <= 4000), last_contacted_at timestamptz, won_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists leads_user_idx on public.leads (user_id, updated_at desc);
alter table public.leads enable row level security;
create policy "leads: owner can do everything" on public.leads for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
